import React from 'react';
import { render, screen } from '@testing-library/react';
import BeesPartner from './BeesPartner';

describe('BeesPartner', () => {
  test('should render without crashing', () => {
    render(<BeesPartner />);
    expect(screen.getByTestId('BeesPartnerIcon')).toBeInTheDocument();
  });
  test('should render icon variant without crashing', () => {
    render(<BeesPartner variant="icon" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Partner Icon')).toBeInTheDocument();
  });
  test('should render vertical variant without crashing', () => {
    render(<BeesPartner variant="vertical" colorType="onDarkBg" />);
    expect(screen.getByTitle('Bees Partner Vertical Logo')).toBeInTheDocument();
  });
  test('should render with a different colorType without crashing', () => {
    render(<BeesPartner colorType="onColorBg" />);
    expect(screen.getByTestId('BeesPartnerIcon')).toBeInTheDocument();
  });
});
